pub fn pop(&mut self) -> Option<bool> {
    if self.len() == 0 {
        return None;
    }

    let last_index = self.len() - 1;
    let last_block_index = last_index / B::bits();
    let bit_index = last_index % B::bits();

    let last_block = &mut self.storage[last_block_index];
    let bit = (*last_block >> bit_index) & B::one() != B::zero();

    // Clear the bit
    *last_block &= !(B::one() << bit_index);

    // If this was the last bit in the last block, we might need to fix the last block
    if last_index == self.len() - 1 {
        self.fix_last_block_with_ones();
    }

    Some(bit)
}

